raw:
{
  "spells": [
    {
      "id": "spell_mind_10",
      "theory": "恐慌刺将魔力凝成极细的一束，沿视线触及目标外层的警觉，再借树脂的黏性把其中的不安放大成短暂恐慌。它不制造持久的恐惧，也不使目标失去判断，只是让心跳与呼吸在片刻间急促起来。目标原有的镇定训练与守心术能把这束魔力挡回，或将其黏性耗尽。",
      "casting": "右手拇指与食指捏住树脂，左手掌心朝向目标张开，念出时值为一息的低音，随后松手让树脂落袋。全程目光不得移开目标肩线。",
      "failure": "施术者指尖会感到一阵反冲的酸麻，目标仅觉耳边一响却无恐慌。若树脂碎裂，施术者自身会陷入数息的慌乱，呼吸急促且无法维持手势。",
      "counters": [
        "目标以守心术稳定呼吸，可把恐慌刺的黏性削弱到无效。",
        "同伴在目标肩背画镇定符文，能引导魔力绕开情绪层。"
      ],
      "socialConsequences": "商队护卫和夜间更夫会视其为挑衅，即便在允许施术的城镇，对未同意的平民使用也会招来乡约责问。精神强迫是重罪，因此公开场合施术前必须取得对方明确同意，否则会被当作袭击。医者和看护人担心它干扰伤者静养，会要求施术者远离病帐。",
      "law": {
        "river": "permit",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时恐慌只持续一两息，且目标容易误认是风冷。",
        "熟练后能稳定触及目标外层的警觉，不再误伤同行者。",
        "高熟练度可精确控制恐慌的起落，仍不延长基础持续时间。",
        "专精者能分辨目标是否已受守心术保护，减少无谓消耗。"
      ]
    },
    {
      "id": "spell_mind_11",
      "theory": "执念松解把魔力织成极缓的细流，通过树脂的黏性附着在目标自愿敞开的表层意识上，一点点稀释轻度强迫暗示的固着。它不阅读记忆，也不改写记忆，只让原本紧绷的念头暂时松脱，像解开绳结而非剪断绳索。被稀释的暗示会随多次照护逐渐减弱，单次施术无法根除。",
      "casting": "施术者与目标对坐，将树脂置于两人之间的布面，双手虚覆其上，以缓慢的吐息引导魔力，每次吐息后停三息，重复七次。目标须保持清醒并自愿。",
      "failure": "若目标中途抗拒，树脂会变黑并散发苦味，细流反冲使施术者头痛。若魔力过急，目标会感到被窥探的恐慌，原有暗示反而暂时收紧，需要更长时间才能再次尝试。",
      "counters": [
        "目标主动握紧树脂并默念自己的姓名，可中断细流并保护记忆。",
        "旁观的照护人用冷水轻拍目标手腕，能提醒其收回敞开的意识。"
      ],
      "socialConsequences": "乡约见证下的民事承诺常要求此类照护在亲属或见证人在场时进行，以防有人借松解之名行篡改之实。城市公会要求施术者登记每一次照护，并确认目标亲自同意。港口船主担心船员被暗中松解而忘记航路，会禁止在卸货区施术。精神强迫与篡改记忆是重罪，违规者将按重罪论处。",
      "law": {
        "river": "permit",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时细流不稳，目标仅觉短暂放松，暗示很快回固。",
        "熟练后能维持七次吐息的均匀细流，减少目标的不适。",
        "高熟练度可辨别暗示的固着层次，仍须多次照护才能稀释。",
        "专精者能控制细流的走向，避免触及目标不愿敞开的记忆。"
      ]
    },
    {
      "id": "spell_mind_12",
      "theory": "眠纱术把魔力铺成一层极薄的纱幕，覆在目标的外层感知上，使疲惫者已有的睡意被轻轻拢住，更快沉入休息。它不制造睡意，也不强迫清醒者入睡，对警觉或精力旺盛者效果微弱。纱幕本身没有黏性，目标受到惊扰或强光刺激便会醒来，纱幕也随之消散。",
      "casting": "施术者以左手在目标额前虚画三道横线，右手握树脂贴近自己心口，每画一线便轻呼一口气，画完后将树脂放回袋中，退开三步。",
      "failure": "若目标过于警觉，纱幕会像被风吹散一样消失，只留下一阵困倦的哈欠。若施术者呼吸紊乱，纱幕会覆盖到施术者自己身上，使其在数息内昏沉，需要同伴唤醒。",
      "counters": [
        "目标用指甲掐掌心，以痛感刺破纱幕，可立刻恢复清醒。",
        "同伴摇动目标肩膀或在其耳边大声报时，能惊散纱幕。"
      ],
      "socialConsequences": "客栈掌柜欢迎它为疲惫旅客助眠，但要求施术者先问明客人意愿，不可对独身旅客随意使用。城市巡夜人担心有人借眠纱术掩护盗窃，会盘问夜间施术者。港口船主允许在船舱内为失眠水手施术，但若因此耽误值夜，则按港务规定追究航运事故责任。",
      "law": {
        "river": "permit",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时纱幕只维持几息，目标容易在半睡中醒来。",
        "熟练后能为疲惫者铺出完整纱幕，缩短入睡所需时间。",
        "高熟练度可控制纱幕厚度，使目标在需要时更容易被唤醒。",
        "专精者能避免纱幕覆盖到施术者自身，仍不改变基础持续时间。"
      ]
    }
  ]
}
